# Parse the ECG data string into a numpy array
ecg_data = np.array([float(x) for x in ecg_data_str.replace('\n', ',').split(',') if x.strip()], dtype=np.float32)

# Load and preprocess ECG data
def preprocess_ecg(ecg_data, window_size=100):
    # Normalize ECG data
    ecg_data = (ecg_data - np.mean(ecg_data)) / np.std(ecg_data)
    
    # Segment into windows
    segments = []
    for i in range(0, len(ecg_data) - window_size, window_size):
        segments.append(ecg_data[i:i + window_size])
    return np.array(segments)

# Generate synthetic PPG data (for demonstration)
def generate_synthetic_ppg(ecg_data, delay=10, sigma=5):
    # Simulate PPG by smoothing and delaying ECG
    ppg_data = gaussian_filter1d(ecg_data, sigma=sigma)
    ppg_data = np.roll(ppg_data, delay)
    ppg_data[:delay] = ppg_data[delay]  # Handle edge effects
    return ppg_data

# Define LSTM model
class ECGtoPPGModel(nn.Module):
    def __init__(self, input_size=1, hidden_size=64, output_size=1):
        super(ECGtoPPGModel, self).__init__()
        self.lstm = nn.LSTM(input_size, hidden_size, batch_first=True)
        self.fc = nn.Linear(hidden_size, output_size)
    
    def forward(self, x):
        out, _ = self.lstm(x)
        out = self.fc(out)
        return out

# Training function
def train_model(model, X, y, epochs=50, batch_size=32, lr=0.001):
    optimizer = torch.optim.Adam(model.parameters(), lr=lr)
    criterion = nn.MSELoss()
    
    for epoch in range(epochs):
        for i in range(0, len(X), batch_size):
            batch_X = torch.tensor(X[i:i + batch_size], dtype=torch.float32).unsqueeze(-1)
            batch_y = torch.tensor(y[i:i + batch_size], dtype=torch.float32).unsqueeze(-1)
            
            optimizer.zero_grad()
            outputs = model(batch_X)
            loss = criterion(outputs, batch_y)
            loss.backward()
            optimizer.step()
        
        if (epoch + 1) % 10 == 0:
            print(f'Epoch [{epoch + 1}/{epochs}], Loss: {loss.item():.4f}')

# Main function
async def main():
    # Use a subset of ECG data for efficiency (e.g., first 10000 samples)
    # Remove the slice to use the full dataset if desired
    ecg_data_subset = ecg_data[:10000]
    
    # Preprocess ECG
    window_size = 100
    X = preprocess_ecg(ecg_data_subset, window_size)
    
    # Generate synthetic PPG
    ppg_data = generate_synthetic_ppg(ecg_data_subset, delay=10, sigma=5)
    y = preprocess_ecg(ppg_data, window_size)  # Segment PPG similarly
    
    # Initialize model
    model = ECGtoPPGModel()
    
    # Train model
    train_model(model, X, y, epochs=50)
    
    # Predict PPG for a sample segment
    sample = torch.tensor(X[:1], dtype=torch.float32).unsqueeze(-1)
    with torch.no_grad():
        predicted_ppg = model(sample).numpy().flatten()
    
    print("Sample predicted PPG (first 10 values):", predicted_ppg[:10])
    
